/**
 * Chat data (DESIGN §6.6): TanStack Query hooks over /chat/sessions and the
 * streamed turn (`POST /chat/sessions/{id}/messages`, Server-Sent Events).
 *
 * The answer is generated by the server whether or not this page keeps
 * listening: after the stream ends (or breaks) the conversation is re-read
 * from `GET /chat/sessions/{id}`, which is what gets rendered for good.
 */
import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { ApiError, api } from './api.js'
import { createSseParser } from './sse.js'

export const CHAT_KEY = ['chat']
export const SESSIONS_KEY = ['chat', 'sessions']
export const sessionKey = (id) => ['chat', 'session', String(id)]

/** Poll interval while another turn (another sibling, or a dropped stream) runs. */
export const GENERATING_POLL_MS = 4000

export const EXAMPLE_PROMPTS = [
  '¿Qué le recetó el neurólogo en la última consulta?',
  '¿Cuándo es la próxima cita de Mamá?',
  'Muéstrame la tendencia de la vitamina B12 de Papá',
]

/** The active conversations, or the archived ones (`archived`, «Archivadas»). */
export function useChatSessions({ pageSize = 20, archived = false } = {}) {
  return useInfiniteQuery({
    queryKey: [...SESSIONS_KEY, { archived }],
    queryFn: ({ pageParam, signal }) =>
      api.get(
        `/chat/sessions?limit=${pageSize}&offset=${pageParam}${archived ? '&archived=true' : ''}`,
        { signal },
      ),
    initialPageParam: 0,
    getNextPageParam: (last, pages) => {
      const loaded = pages.reduce((n, p) => n + p.items.length, 0)
      return loaded < last.total && last.items.length > 0 ? loaded : undefined
    },
    // A sibling may be answering right now: keep the "Respondiendo…" marks fresh.
    refetchInterval: (query) =>
      query.state.data?.pages.some((p) => p.items.some((s) => s.generating))
        ? GENERATING_POLL_MS
        : false,
  })
}

/**
 * One conversation. While a turn runs that this page is not streaming
 * (`generating` and `poll`), it is re-read every few seconds.
 */
export function useChatSession(id, { poll = true } = {}) {
  return useQuery({
    queryKey: sessionKey(id),
    queryFn: ({ signal }) => api.get(`/chat/sessions/${id}`, { signal }),
    enabled: id != null,
    retry: (count, error) => !(error?.status >= 400 && error?.status < 500) && count < 1,
    refetchInterval: (query) => (poll && query.state.data?.generating ? GENERATING_POLL_MS : false),
  })
}

export function useCreateChatSession() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: () => api.post('/chat/sessions', {}),
    onSuccess: (session) => {
      queryClient.setQueryData(sessionKey(session.id), { ...session, messages: [] })
      queryClient.invalidateQueries({ queryKey: SESSIONS_KEY })
    },
  })
}

/** Archive (`archived: true`) or restore a conversation (any member; 409 while answering). */
export function useArchiveChatSession() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: ({ id, archived }) => api.patch(`/chat/sessions/${id}`, { archived }),
    onSuccess: (session) => {
      queryClient.setQueryData(sessionKey(session.id), (old) => (old ? { ...old, ...session } : old))
      queryClient.invalidateQueries({ queryKey: SESSIONS_KEY })
    },
  })
}

/** Delete a conversation for good (its creator or an admin: `can_delete`). */
export function useDeleteChatSession() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (id) => api.delete(`/chat/sessions/${id}`),
    onSuccess: (_data, id) => {
      queryClient.removeQueries({ queryKey: sessionKey(id) })
      queryClient.invalidateQueries({ queryKey: SESSIONS_KEY })
    },
  })
}

/** Spanish message for a failed archive / delete. */
export function sessionActionError(error) {
  if (error instanceof ApiError) {
    if (error.status === 409) return 'Se está generando una respuesta. Espera a que termine e intenta de nuevo.'
    if (error.status === 403) return 'Solo quien inició la conversación o un administrador puede eliminarla.'
    if (error.status === 404) return 'Esta conversación ya no existe.'
  }
  return 'No se pudo completar la acción. Intenta de nuevo.'
}

/**
 * Sends one message and calls `onEvent({event, data})` for each SSE event
 * (`start`, `delta`, `tool`, `file`, `suggestion`, `error`, `message`, `title`, `done`; `data` is
 * parsed JSON). `onOpen()` runs once the response is a 200: by then the
 * server has stored the prompt and holds the session's lock, so the turn
 * runs even if the stream breaks before `start`. Resolves when the stream ends. Rejects with ApiError for an
 * HTTP error before the stream (404, 409, 422, 503), with an AbortError when
 * `signal` aborts, and with a TypeError (or similar) when the connection drops.
 */
export async function streamChatMessage(sessionId, text, { onEvent, onOpen, signal } = {}) {
  const response = await fetch(`/api/v1/chat/sessions/${sessionId}/messages`, {
    method: 'POST',
    credentials: 'same-origin',
    headers: {
      Accept: 'text/event-stream',
      'Content-Type': 'application/json',
      'X-Requested-With': 'fetch',
    },
    body: JSON.stringify({ text }),
    signal,
  })
  if (!response.ok) {
    let body = null
    try {
      body = await response.json()
    } catch {
      // not JSON (proxy error page)
    }
    const detail = typeof body?.detail === 'string' ? body.detail : null
    throw new ApiError(response.status, detail || `Error ${response.status}`, body)
  }
  onOpen?.()

  const parser = createSseParser(({ event, data }) => {
    let parsed
    try {
      parsed = data ? JSON.parse(data) : {}
    } catch {
      return // a malformed event is skipped, the stored session is the truth
    }
    onEvent?.({ event, data: parsed })
  })
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  for (;;) {
    const { value, done } = await reader.read()
    if (done) break
    parser.push(decoder.decode(value, { stream: true }))
  }
  parser.push(decoder.decode())
  parser.end()
}

/** Spanish message for a failed send (before the stream started). */
export function sendErrorMessage(error) {
  if (error instanceof ApiError) {
    if (error.status === 409)
      return 'Hay una respuesta en curso en esta conversación. Espera a que termine e inténtalo de nuevo.'
    if (error.status === 503)
      return 'El chat no está configurado todavía. Avísale a quien administra la aplicación.'
    if (error.status === 404) return 'Esta conversación ya no existe.'
    if (error.status === 401) return 'Tu sesión expiró. Vuelve a entrar.'
    if (error.status === 422) return 'El mensaje está vacío o es demasiado largo.'
    return 'No se pudo enviar el mensaje. Inténtalo de nuevo.'
  }
  return 'Sin conexión con el servidor. Revisa tu conexión e inténtalo de nuevo.'
}

export const CONNECTION_LOST =
  'Se perdió la conexión; la respuesta sigue generándose. La mostraremos en cuanto esté lista.'

/**
 * Stored messages grouped for display: each family prompt, then one answer
 * block per run of assistant rows (a tool round stores its own row). The
 * block joins their texts, lists the tool statuses, keeps the last row's
 * status/error and every file and proposal (`suggestions`, #41).
 */
export function groupMessages(messages) {
  const out = []
  for (const m of messages) {
    if (m.kind === 'prompt') {
      out.push({ type: 'prompt', key: `p${m.id}`, message: m })
      continue
    }
    let block = out[out.length - 1]
    if (block?.type !== 'answer') {
      block = {
        type: 'answer',
        key: `a${m.id}`,
        texts: [],
        tools: [],
        attachments: [],
        suggestions: [],
      }
      out.push(block)
    }
    if (m.text?.trim()) block.texts.push(m.text)
    for (const t of m.tools ?? []) block.tools.push(t.status)
    block.attachments.push(...(m.attachments ?? []))
    block.suggestions.push(...(m.suggestions ?? []))
    block.status = m.status
    block.error = m.error
    block.lastId = m.id
  }
  for (const b of out) {
    if (b.type !== 'answer') continue
    b.text = b.texts.join('\n\n')
    b.tools = [...new Set(b.tools)]
  }
  return out
}

const RTF = new Intl.RelativeTimeFormat('es', { numeric: 'auto' })
const DAY_FMT = new Intl.DateTimeFormat('es-PA', {
  day: 'numeric',
  month: 'short',
  year: 'numeric',
  timeZone: 'America/Panama',
})

/** «hace 5 minutos», «ayer», or a date for anything older than a week. */
export function relativeTime(iso, now) {
  if (!iso) return ''
  const seconds = Math.round((new Date(iso).getTime() - now) / 1000)
  const abs = Math.abs(seconds)
  if (abs < 60) return 'hace un momento'
  if (abs < 3600) return RTF.format(Math.round(seconds / 60), 'minute')
  if (abs < 86400) return RTF.format(Math.round(seconds / 3600), 'hour')
  if (abs < 7 * 86400) return RTF.format(Math.round(seconds / 86400), 'day')
  return DAY_FMT.format(new Date(iso))
}
